def comps_of(g,sccolor=None):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    sc=Counter(x for row in g for x in row).most_common()[-1][0]
    for i in range(H):
        for j in range(W):
            if g[i][j]==sc and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True;s=set()
                while q:
                    a,b=q.popleft(); s.add((a,b))
                    for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni,nj=a+di,b+dj
                        if 0<=ni<H and 0<=nj<W and g[ni][nj]==sc and (ni,nj) not in s:
